<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderSamlIdpCertAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderSamlIdpCertAccessor trait.
 *
 * Covers null default, string/VO assignment via withSamlIdpCert,
 * getSamlIdpCert/samlIdpCert accessors, and isSamlIdpCertChanged with/without original.
 */
class TenantLoginProviderSamlIdpCertAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSamlIdpCert creates a new instance with the SamlIdpCert set
     * from a string value, and getSamlIdpCert returns the primitive string.
     */
    public function testWithSamlIdpCertFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpCertAccessorUnitTest();

        // Act
        $result = $holder->withSamlIdpCert('store://bin');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('bin', $result->getSamlIdpCert());
    }
    /**
     * Asserts that withsamlIdpCert has access to the value object
     * from a string value, and getSamlIdpCert returns the primitive string.
     */
    public function testWithSamlIdpCertFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpCertAccessorUnitTest();

        // Act
        $result = $holder->withSamlIdpCert('store://bin');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('bin', $result->samlIdpCert()->value());
    }
    public function testChangedSamlIdpCert(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpCertAccessorUnitTest();
        $original = $holder->withSamlIdpCert('store://bin');
        $same = $holder->withSamlIdpCert('store://bin');
        $modified = $holder->withSamlIdpCert('store://obin');

        // Act
        $unchanged = $holder->isSamlIdpCertChanged();
        $withSame = $original->isSamlIdpCertChanged($same);
        $withDiferent = $original->isSamlIdpCertChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderSamlIdpCertAccessorUnitTest
{
    use TenantLoginProviderSamlIdpCertAccessor;
}
